import { Component } from '@angular/core';

@Component({
  selector: 'app-home',
  templateUrl: './home.component.html',
  styleUrls: ['./home.component.less'],
  standalone: true
})
export class HomeComponent {
}
<div class="p-4">
  <div class="container">
    <h1>Home</h1>
    <p>You are logged in!!</p>
    <p>This is the home page</p>
  </div>
</div>
